window.NOTES={"version":71,"chapters":[{"number":1,"title":"信息技术与计算机文化","summary":"计算机发展、信息表示、硬件、软件与计算机系统的基础概念。","sections":[{"id":"1.1","title":"信息与信息技术"},{"id":"1.2","title":"计算机技术概论"},{"id":"1.3","title":"计算机中信息的表示"},{"id":"1.4","title":"计算机系统"},{"id":"1.5","title":"微型计算机系统"}]},{"number":2,"title":"Windows 10 操作系统","summary":"操作系统特征、Windows界面、文件管理、系统设置与维护。","sections":[{"id":"2.1","title":"操作系统概述"},{"id":"2.2","title":"Windows 10 基础"},{"id":"2.3","title":"文件和文件夹管理"},{"id":"2.4","title":"控制面板"},{"id":"2.5","title":"Windows 10 的系统维护"},{"id":"2.6","title":"Windows 10 的实用工具"}]},{"number":3,"title":"字处理软件 Word 2016","summary":"文档编辑、格式排版、表格、图文混排与长文档功能。","sections":[{"id":"3.1","title":"使用 Office 2016 应用程序"},{"id":"3.2","title":"Word 2016 的基本操作"},{"id":"3.3","title":"文档格式化与排版"},{"id":"3.4","title":"表格制作"},{"id":"3.5","title":"图文混排"},{"id":"3.6","title":"文档的保护与打印"},{"id":"3.7","title":"Word 2016 的高级应用"}]},{"number":4,"title":"电子表格系统 Excel 2016","summary":"工作表操作、公式与函数、格式化、数据处理和图表。","sections":[{"id":"4.1","title":"Excel 2016 概述"},{"id":"4.2","title":"Excel 2016 的基本操作"},{"id":"4.3","title":"Excel 公式与函数"},{"id":"4.4","title":"格式化工作表"},{"id":"4.5","title":"数据处理"},{"id":"4.6","title":"使用图表"}]},{"number":5,"title":"演示文稿软件 PowerPoint 2016","summary":"幻灯片组织、外观、动画、切换与放映设置。","sections":[{"id":"5.1","title":"PowerPoint 2016 基础"},{"id":"5.2","title":"幻灯片页面设计"},{"id":"5.3","title":"幻灯片页面外观的修饰"},{"id":"5.4","title":"动画效果和动作设置"},{"id":"5.5","title":"播放和打印演示文稿"},{"id":"5.6","title":"演示文稿的其他功能"}]},{"number":6,"title":"计算机网络及网页制作","summary":"网络结构、Internet应用、HTML、网页与信息检索。","sections":[{"id":"6.1","title":"计算机网络概述"},{"id":"6.2","title":"计算机网络系统"},{"id":"6.3","title":"Internet 基础和应用"},{"id":"6.4","title":"网页、网页制作及 HTML 简介"},{"id":"6.5","title":"信息检索"}]},{"number":7,"title":"数字多媒体技术基础","summary":"多媒体特征、媒体元素、图像格式、颜色和视频。","sections":[{"id":"7.1","title":"数字多媒体技术概述"},{"id":"7.2","title":"数字多媒体系统组成及常用软件"},{"id":"7.3","title":"常用多媒体制作软件"}]},{"number":8,"title":"信息安全","summary":"安全属性、恶意软件、防火墙、密码技术和信息伦理。","sections":[{"id":"8.1","title":"信息安全概述"},{"id":"8.2","title":"计算机病毒"},{"id":"8.3","title":"防火墙"},{"id":"8.4","title":"Windows 10 操作系统安全"},{"id":"8.5","title":"信息伦理"}]},{"number":9,"title":"信息技术前沿","summary":"虚拟现实、云计算、物联网、区块链与人工智能。","sections":[{"id":"9.1","title":"虚拟现实和增强现实"},{"id":"9.2","title":"云计算和高性能计算"},{"id":"9.3","title":"物联网技术"},{"id":"9.4","title":"大数据技术"},{"id":"9.5","title":"区块链技术"},{"id":"9.6","title":"人工智能"},{"id":"9.7","title":"量子信息"},{"id":"9.8","title":"元宇宙"}]},{"number":10,"title":"数据库技术基础","summary":"关系数据库、数据库管理系统、关系运算、SQL与NoSQL。","sections":[{"id":"10.1","title":"数据库技术基础"},{"id":"10.2","title":"数据库管理系统"},{"id":"10.3","title":"数据库设计与 NoSQL"}]},{"number":11,"title":"计算思维","summary":"计算思维、算法表示、算法特征和基本控制结构。","sections":[{"id":"11.1","title":"计算思维"},{"id":"11.2","title":"计算思维与算法"},{"id":"11.3","title":"算法的控制结构"},{"id":"11.4","title":"面向对象程序设计"},{"id":"11.5","title":"基础算法设计思想"}]}],"notes":[{"q":3,"chapter":11,"section":"11.1","type":"单选","topic":"计算思维","title":"计算思维不是计算机科学家的专属思维","trigger":"真题直接考查计算思维的适用范围和常见方法。","conclusion":"计算思维是一套可用于多学科问题求解的思维方法，并非计算机科学家专属。","points":["常见过程包括分解、抽象、模式识别和算法设计。","它可以借助计算机，也可以先在纸面上形成问题模型。","医学、管理、工程和日常决策都可使用计算思维。","抽象保留与目标相关的要素、忽略暂时无关细节；自动化把明确的过程交给机器执行。计算思维是人的问题求解方式，不只是机械操作计算机。","教学示例：统计班级不及格人数。先确定输入是有效成绩列表，输出是不及格人数；规则为成绩小于60，不必保留与计数无关的姓名和座位号。","分解过程：核验输入→计数器C置0→逐个读成绩→若成绩\u003c60则C加1→读完输出C。这把现实任务转为可由人或机器执行的步骤。","用59、60、80检验应输出1；再检查空列表输出0、全部不及格是否等于列表长度。缺考或非法成绩如何处理应先写进输入规则，而不是让程序自行猜测。","计算思维关注怎样表示问题并形成可执行的求解过程：先明确要解决什么、哪些信息重要，再把步骤表达得足够清楚，供人或机器执行。分解、抽象、模式识别、算法化是常用理解角度，不是唯一固定清单；只会点击软件按钮不等于已经掌握这种思维。","从任务到解法可分为明确需求与输入输出、建立简化模型、设计步骤、检查结果、必要时编码实现。模式识别是在不同实例中找可复用规律，例如统计不及格和统计缺勤都可采用“逐项判断、符合时计数”；判断条件不同，不能照搬结论。"],"boundary":"计算思维不等于会操作软件，也不等于任何问题都必须写程序。","id":"y2025q4","sources":[{"year":2023,"q":3,"type":"单选"},{"year":2025,"q":4,"type":"单选"},{"year":2021,"q":23,"type":"多选","page":4}],"keys":["2023-3","2025-4","2021-23"],"related":[{"id":"y2026q42","label":"伪代码用接近自然语言的结构描述算法","reason":"把分解和抽象所得的求解过程写成伪代码，可在选择具体编程语言之前讨论算法。"},{"id":"y2025q24","label":"面向对象用类、对象、封装和消息组织程序","reason":"类把共同属性与行为抽象出来，是计算思维中保留关键要素的一种程序组织实例。"}],"pointGroups":[{"title":"先理解计算思维与常用方法","indices":[7,0,3,1,2,8]},{"title":"用成绩统计走完问题求解过程","indices":[4,5,6]}],"pointPresentation":{"7":{"title":"计算思维的对象与常用角度","navigationLabel":"计算思维的对象与常用角度"},"8":{"title":"问题求解过程与模式识别","navigationLabel":"问题求解过程与模式识别"}}},{"q":42,"chapter":11,"section":"11.1","type":"填空","topic":"算法表示","title":"伪代码用接近自然语言的结构描述算法","trigger":"题目要求填写一种不依赖具体编程语言的算法表示方法。","conclusion":"伪代码用结构化、近似程序的文字表达算法逻辑，不要求遵守某门语言的完整语法。","points":["伪代码应清楚体现输入、处理、输出和控制结构。","它便于编码前讨论逻辑。例如求3、8、5的最大值：m先取3，看到8更大就改为8，再与5比较后保持8，最后输出8。若只写“选一个合适的数”，因为“合适”未定义，无法据此执行。","流程图也可表示算法，但形式是图形符号和流程线。","自然语言、伪代码、流程图可描述算法步骤；E-R图描述实体及联系，不是算法流程图。","算法是为解决一类问题而规定的明确、有限、可执行步骤；表示法只是把这些步骤写出来或画出来。自然语言便于交流，但需避免歧义；流程图突出路径和条件；伪代码突出结构与变量。换一种表示法，不等于换了所解决的问题。","三数取最大值的完整伪代码可写为：输入a、b、c；m←a；若b>m则m←b；若c>m则m←c；输出m。输入3、8、5时m依次为3、8、8。两个判断都要执行，不能擅自把第二个改成第一个的“否则”；输入3、8、9时仍须继续比较9。","常见程序流程图用起止框表示开始/结束、矩形表示处理或赋值、平行四边形表示输入/输出、菱形表示判断，箭头表示下一步。判断框还要读清分支标注；同样的框，连线方向不同也可能执行不同算法。具体图形记号以题目约定为准。"],"boundary":"伪代码没有唯一语法，却仍应保持关键词、缩进和变量含义一致。","id":"y2026q42","sources":[{"year":2026,"q":42,"type":"填空"},{"year":2022,"q":5,"type":"单选"}],"keys":["2026-42","2022-5"],"related":[{"id":"y2026q6","label":"算法必须确定、可行、有限并产生输出","reason":"伪代码没有统一语法，但描述的算法仍需明确、可行、有输出并能终止。"},{"id":"y2026q5","label":"顺序、分支和循环可以相互嵌套","reason":"顺序、分支与循环是伪代码中表达控制逻辑的基本结构，缩进应清楚体现嵌套关系。"},{"id":"y2025q11","label":"数据库设计不因规模小而省略","reason":"流程图描述算法步骤，E-R图描述实体及联系；看见图形表达不能把两者归为同一种设计。"}],"pointGroups":[{"title":"算法与三种表示方式","indices":[4,0,2,3]},{"title":"完整伪代码和流程图符号","indices":[1,5,6]}],"pointPresentation":{"4":{"title":"算法与表示法","navigationLabel":"算法与表示法"},"5":{"title":"三数最大值完整伪代码","navigationLabel":"三数最大值完整伪代码"},"6":{"title":"流程图常见符号","navigationLabel":"流程图常见符号"}}},{"q":4,"chapter":11,"section":"11.2","type":"单选","topic":"算法特征与评价","title":"算法必须确定、可行、有限并产生输出","trigger":"真题从输出、可行性和实现前评价考查算法的基本特征。","conclusion":"算法可以没有外部输入，但至少有一个输出；每一步应确定、可行，并在有限步骤后结束，也可以在编码前分析正确性与复杂度。","points":["确定性要求每一步含义明确，可行性要求操作能在有限资源下执行。","时间复杂度和空间复杂度可依据算法结构分析。","程序是算法的一种实现，测试实现不能代替算法论证。","算法允许零个或多个输入，但必须有一个或多个输出；“输入必须有、输出可以无”把条件写反。","辗转相除法每轮用“当前除数、非零余数”作为下一轮输入。例如48÷18余12，18÷12余6，12÷6余0，输出当前除数6。非零余数逐轮严格变小且不能无限下降，因此会终止；首轮整除时直接输出该轮除数。","算法面向一类问题，对满足输入约定的不同实例都应成立，而非只碰巧算对一组数。先确定输入域与任务，再看步骤和终点；程序用某种编程语言实现这些步骤，同一算法可以有不同语言实现，也可先由人手工追踪。下方最大公约数演示限定两个正整数，这是演示输入域，不是所有算法都必须有两个输入。","确定性要求步骤含义明确，并不要求不同输入产生同一个数值。理论上可计算与现实中能高效完成也不同：即使存在求解步骤，输入规模很大时仍可能超出可接受的时间或存储资源。不能由理论可计算推出任意现有电脑都能迅速求解。"],"boundary":"伪代码仍需转成可执行程序；“程序跑起来”也不等于算法正确或高效。","id":"y2026q6","sources":[{"year":2024,"q":4,"type":"单选"},{"year":2025,"q":5,"type":"单选"},{"year":2026,"q":6,"type":"单选"},{"year":2022,"q":6,"type":"单选"}],"keys":["2024-4","2025-5","2026-6","2022-6"],"related":[{"id":"y2026q42","label":"伪代码用接近自然语言的结构描述算法","reason":"可先用伪代码表达算法，再检查每一步含义、输入域、输出和终止条件是否清楚。"},{"id":"y2022q33","label":"时间复杂度与空间复杂度不必同向变化","reason":"算法在编码前即可分析时间和空间复杂度，运行测试与增长趋势分析回答不同问题。"},{"id":"y2021q33","label":"流程图要按箭头追踪，判断位置决定是否先执行一轮","reason":"循环的初值、变量推进和判断位置共同决定结果及能否终止，可用实际追踪检验算法条件。"}],"pointGroups":[{"title":"问题、输入域与算法特征","indices":[5,0,3,6]},{"title":"用辗转相除检查终止","indices":[4]},{"title":"算法评价与程序实现","indices":[1,2]}],"workedExamples":[{"year":2024,"q":4,"questionSummary":"判断算法是否必须编程后才能评价。","reasoning":["算法是问题求解的明确步骤，程序是算法的一种实现。","即使尚未编码，也能检查步骤是否正确、是否终止，并估算主要操作次数与额外空间。","因此“必须实现后才能评价”的绝对前提不成立；具体运行时间还会受语言实现和机器环境影响。"],"pitfall":"把抽象算法的分析等同于程序跑出来的秒数。","transfer":"拿两个寻找最大值的方法先数比较次数，再谈实现语言；能分析复杂度不等于已经知道实测耗时。","sourceURL":"https://www.aipta.com/article/10360.html","sourceStatus":"2024原卷完整题干及全部选项已读；配套答案已核，未据此称官方答案","historicalVersionNote":""}],"pointPresentation":{"5":{"title":"输入域、算法与程序","navigationLabel":"输入域、算法与程序"},"6":{"title":"确定性与现实资源边界","navigationLabel":"确定性与现实资源边界"}}},{"q":33,"target":null,"chapter":11,"section":"11.2","topic":"算法复杂度","title":"时间复杂度与空间复杂度不必同向变化","conclusion":"时间复杂度描述运算量随输入规模增长的趋势；空间复杂度描述所需存储空间的增长趋势，两者没有必然正比例关系。","points":["同一问题可用缓存结果换取更少重复计算，这是以空间换时间。","逐个扫描n项求和，主要加法次数随n成比例增长，通常为O(n)时间；只保留当前累计值，需要O(1)额外空间。O(1)表示额外空间不随n增长，不是完全不占空间。","前缀和把“到当前位置为止的和”预先存好。例如数据3、5、2对应前缀和0、3、8、10，第2至3项的和可算10−3=7，不用再逐项相加。建表需O(n)时间和空间，之后每次区间求和为O(1)。","枚举检查候选解，递推从已知小规模结果推进，分治把问题分成较小子问题再合并结果；是否适用取决于问题结构。二分查找要依赖有序数据，不能对任意无序表直接使用。","分析循环时看实际执行次数：从1到n每次加1通常是线性次数；每次把规模减半通常是对数次数。嵌套循环不能只数层数，还要检查各层边界及依赖关系。","先约定输入规模与统计口径，再谈复杂度。本章示例以主要运算次数观察增长趋势，以“额外空间”表示不含原输入的辅助存储；O(n)等记号不等于准确次数。一次实测更快不能单独证明复杂度更低，增加缓存也不保证任何查询都更划算。"],"boundary":"复杂度描述规模增长趋势，不是一次运行秒数或某台电脑的内存容量；应说明是否统计额外空间。前缀和适合数据不变且有多次查询的情形，数据修改后原缓存可能需要更新。","type":"判断","trigger":"从算法复杂度的判断与应用整理。","id":"y2022q33","sources":[{"year":2022,"q":33,"type":"判断"}],"keys":["2022-33"],"related":[{"id":"y2024q69","label":"一趟升序冒泡把最大值推到右端","reason":"冒泡排序通常用O(n²)时间和O(1)额外空间，是时间与空间增长不必同向的具体例子。"},{"id":"y2022q43","label":"先初始化，再累加，再推进循环变量","reason":"将1至10累加推广到n项，逐项扫描需O(n)时间而累计变量只需O(1)额外空间。"},{"id":"y2026q45","label":"算力表示计算设备处理数据的能力","reason":"复杂度描述随输入规模的增长，算力描述设备处理能力，不能用一次运行秒数代替复杂度。"}],"pointGroups":[{"title":"先定评价口径，再比较时空取舍","indices":[5,0,1,2]},{"title":"典型策略与增长趋势的最小联系","indices":[3,4]}],"pointPresentation":{"5":{"title":"时间与额外空间的统计口径","navigationLabel":"时间与额外空间的统计口径"}}},{"q":3,"target":null,"page":1,"chapter":11,"section":"11.2","topic":"队列","title":"队列先进先出，多队列交错不能打乱各自顺序","conclusion":"队列从队尾加入、从队头取出，遵循FIFO；多个队列可以交替出队，但各自内部先后顺序保持不变。","points":["车道一按A、B、C、D排队，车道二按E、F、G、H排队，每次只能放行某车道队首。","ABEFCDGH是合法交错；AFEBCDGH中F先于E，违反第二队列顺序。","判断一串输出是否合法，可分别抽出属于每个队列的元素，检查相对次序是否保持。","栈是后进先出LIFO，操作限制与队列不同。"],"boundary":"队列先后只约束本队列；不能据此断言A必定先于另一队列的E。","type":"单选","trigger":"围绕队列的识别、应用与易错边界整理。","id":"y2021q3","sources":[{"year":2021,"q":3,"type":"单选"}],"keys":["2021-3"],"related":[{"id":"y2026q7","label":"并发、共享、虚拟和异步描述不同操作系统现象","reason":"多队列交替出队可帮助理解任务交错推进；调度次序变化不代表各自应守的操作规则消失。"}]},{"q":25,"chapter":11,"section":"11.3","type":"多选","topic":"控制结构","title":"顺序、分支和循环可以相互嵌套","trigger":"两道题综合判断三种基本控制结构的含义和嵌套关系。","conclusion":"顺序按先后执行，分支按条件选择路径，循环在终止条件控制下重复；三者可以结构化嵌套。","points":["分支可表达条件成立执行A，否则执行B。","循环由循环体和循环控制条件构成。","结构化组合有助于保持流程可追踪。","顺序结构按既定先后执行，赋值会改变后续语句读到的值。例如x←2；x←x+3；输出x，结果为5。顺序并非要求所有表达式都不含比较，而是描述控制流按先后推进。","分支由条件选择路径。若成绩\u003c60则输出“不及格”，否则输出“及格”，一次只走其中一条；两个独立的“若”则各自判断，可能都执行。需要多个互斥结果时可用多分支，但必须先看题目各条件如何衔接。","追踪循环统一检查初值、条件、循环体和更新：写出初始变量，沿箭头执行，逐步改值，检查继续条件，直到出口才读最终输出。先判断型可能0次，后判断型至少1次；漏掉推进或在循环内反复清零累加器，会破坏原来的计算任务。Excel的IF是返回结果的函数，不能仅凭名称把它等同于整段程序控制流。"],"boundary":"“外层是顺序结构”不意味着内部不能含分支或循环。","id":"y2026q5","sources":[{"year":2025,"q":25,"type":"多选"},{"year":2026,"q":5,"type":"单选"}],"keys":["2025-25","2026-5"],"related":[{"id":"y2026q42","label":"伪代码用接近自然语言的结构描述算法","reason":"伪代码用关键词和缩进表达顺序、分支、循环及其嵌套，便于在编码前检查逻辑。"},{"id":"y2023q69","label":"计数循环要同时检查初值、边界、条件和累加器","reason":"处理多名学生并只统计不及格者，是循环中嵌套分支的完整实例。"},{"id":"y2024q69","label":"一趟升序冒泡把最大值推到右端","reason":"冒泡排序在重复扫描中进行相邻比较并按条件交换，可练习追踪循环与分支的组合。"}],"pointGroups":[{"title":"顺序与条件路径","indices":[3,0,4]},{"title":"循环和结构化组合","indices":[1,5,2]}],"pointPresentation":{"3":{"title":"顺序执行和赋值","navigationLabel":"顺序执行和赋值"},"4":{"title":"独立判断与互斥分支","navigationLabel":"独立判断与互斥分支"},"5":{"title":"循环追踪四要素","navigationLabel":"循环追踪四要素"}}},{"q":43,"target":null,"chapter":11,"section":"11.3","topic":"累加循环","title":"先初始化，再累加，再推进循环变量","conclusion":"S=0、i=1；当i≤10时执行S=S+i、i=i+1，最终S为55。","points":["S保存累计结果，i保存当前加数。从(S,i)=(0,1)开始，前三轮执行后依次为(1,2)、(3,3)、(6,4)：每轮先把当前i加进S，再推进i。","S应在循环外初始化。若每轮相加前都重新令S=0，前面的和就被覆盖；本例最终只会留下最后一次的加数10。","最后一次相加使用i=10，之后i变成11，条件不成立才退出。","可用等差数列1+…+10=10×11÷2核验，不替代逐步理解循环。"],"boundary":"S=S+i是赋值更新，不是代数恒等式；把推进语句提前会改变被累加的数列。","type":"填空","trigger":"从累加循环的判断与应用整理。","id":"y2022q43","sources":[{"year":2022,"q":43,"type":"填空"}],"keys":["2022-43"],"related":[{"id":"y2021q33","label":"流程图要按箭头追踪，判断位置决定是否先执行一轮","reason":"将判断框移到循环体后，或改变更新顺序与边界等号，会改变参与累加的项。"},{"id":"y2023q69","label":"计数循环要同时检查初值、边界、条件和累加器","reason":"求和累加器加当前数值，人数计数器只在条件成立时加1；两者都应在循环外初始化。"},{"id":"y2022q33","label":"时间复杂度与空间复杂度不必同向变化","reason":"逐项累加可推广为O(n)时间、O(1)额外空间，前缀和则展示为多次查询增加存储的取舍。"}],"pointGroups":null},{"q":33,"target":null,"page":5,"chapter":11,"section":"11.3","topic":"先执行后判断","title":"流程图要按箭头追踪，判断位置决定是否先执行一轮","conclusion":"本例先执行S=S+k，再令k=k+3，最后判断k＜10；从S=0、k=1开始，累加1、4、7后输出12。判断位置、条件方向和变量更新顺序要一起追踪。","points":["每轮记录执行前的k、累加后的S、更新后的k以及继续条件真假，按流程箭头实际经过的顺序执行。","第一轮S=1、k=4；第二轮S=5、k=7；第三轮S=12、k=10，条件不成立退出，因此10未被累加。","把继续条件改成k≤10，会再累加10，随后k变为13，输出变为22；边界等号是否存在会改变执行次数。","后测试循环先执行循环体，至少执行一次；先测试循环先判断，初始条件不成立时可能执行0次。","例如仍取S=0、k=1，但边界设为1：本例后测试写法会先加1再退出；将条件移到循环体之前则一次也不加。","S应在循环外初始化；循环变量必须按规则推进，使退出条件最终能满足。赋值S=S+k是用旧值计算后写回，不是代数恒等式。"],"boundary":"判断框移到循环体前后、把＜改成≤、或把k的更新提前，都可能改变结果；箭头上的“是/否”通向哪里也必须与条件一起阅读。","type":"填空","trigger":"围绕先执行后判断的识别、应用与易错边界整理。","id":"y2021q33","sources":[{"year":2021,"q":33,"type":"填空"}],"keys":["2021-33"],"comparison":{"headers":["条件与结构","累加项","输出"],"rows":[["本例后测试，k＜10","1、4、7","12"],["本例后测试，k≤10","1、4、7、10","22"],["边界1，后测试","1","1"],["边界1，先测试","无","0"]]},"related":[{"id":"y2022q43","label":"先初始化，再累加，再推进循环变量","reason":"对照先判断的累加循环，观察同样的初始化和更新操作如何因判断位置不同改变执行次数。"},{"id":"y2026q5","label":"顺序、分支和循环可以相互嵌套","reason":"先辨认顺序执行、条件判断和循环回边，再按流程箭头追踪每一轮。"},{"id":"y2026q6","label":"算法必须确定、可行、有限并产生输出","reason":"循环变量推进和退出条件是算法有限性的具体要求，初始条件与边界情况也需覆盖。"}],"pointGroups":[{"title":"初始化并按真实执行顺序追踪状态","indices":[0,1,5]},{"title":"改变边界或判断位置后再比较","indices":[2,3,4]}]},{"q":69,"chapter":11,"section":"11.3","type":"分析","topic":"循环计数","title":"计数循环要同时检查初值、边界、条件和累加器","trigger":"两道连续分析题补全处理45名学生的循环条件，并解释不及格人数累加语句。","conclusion":"先用i保证每人成绩恰好处理一次，再用C只统计不及格者。若从i=1开始，每轮处理一人后加1，45人用i≤45；C在循环前置0，成绩＜60时才执行C=C+1。","points":["初值和边界必须配套：i从1到45，含两端，共45次；i从0到44，同样45次，可写i＜45。若把i=1与i＜45搭配，只处理44人；把i=0与i≤45搭配则处理46次。","C=C+1是赋值：先读出旧C，加1，再写回C；不是解方程。i记录处理进度，C记录满足条件的人数，即使某人成绩及格，i也仍要推进。","只有成绩＜60时才增加C；恰好60分不满足这一条件。循环总次数等于处理人数，分支执行次数才是不及格人数。","用三个人缩小推演：成绩依次59、60、58，C从0开始；读59后C=1，读60后仍为1，读58后C=2。共执行3轮，但只执行2次C=C+1，最终输出2。","C必须在循环前初始化一次。若每轮都把C置0，本例最终得到1，只反映最后一人成绩；若漏掉初始化，累计值没有可靠起点。"],"boundary":"这里按“先判断是否还有人→读取本人成绩→按条件计数→推进i”推演；改变读入位置或更新顺序后应重新走一遍。初值、最后一次处理的序号、退出时的i与最终C是四个不同问题。","id":"y2023q69","sources":[{"year":2023,"q":69,"type":"分析"},{"year":2023,"q":70,"type":"分析"}],"keys":["2023-69","2023-70"],"related":[{"id":"y2022q43","label":"先初始化，再累加，再推进循环变量","reason":"比较S=S+i与C=C+1，区分累计数值和累计满足条件的记录数，并检查初始化位置。"},{"id":"y2026q5","label":"顺序、分支和循环可以相互嵌套","reason":"不及格计数是在循环内嵌套分支，只有分支条件成立才更新计数器。"},{"id":"y2021q51","label":"COUNTIF、COUNTIFS与AVERAGEIF：条件计数和条件平均","reason":"COUNTIF把逐行判断后计数封装为表格函数，多条件计数仍要求同一记录满足相应条件。"}],"pointGroups":[{"title":"初值、边界与每轮执行顺序","indices":[0,1]},{"title":"不及格条件与三值计数轨迹","indices":[2,3]},{"title":"初始化位置为何改变结果","indices":[4]}]},{"q":24,"chapter":11,"section":"11.4","type":"多选","topic":"面向对象","title":"面向对象用类、对象、封装和消息组织程序","trigger":"题目要求识别面向对象程序设计的基本思想与方法。","conclusion":"面向对象以类和对象为核心，通过封装组织数据与操作，并通过消息或方法调用建立对象协作。","points":["类描述一类对象共同的属性和行为。例如“学生”类可规定学号、姓名、成绩等属性，以及修改成绩等方法。","对象是类的具体实例。“学号01的王宁”和“学号02的李明”可来自同一学生类，但各自保存自己的成绩状态。","封装把数据与操作组织在一起，并控制外部访问。例如通过“修改成绩”方法检查0—100的范围，再更新对象内部成绩；调用者按公开接口使用，不必直接改内部存储。","继承复用或扩展已有类型；多态使相同接口可由不同对象给出各自实现。例如同样调用“计算面积”，圆对象按圆的规则计算，矩形对象按长×宽计算。消息或方法调用用来请求对象完成操作。","沿一次调用看对象状态：同一“学生”类建立A、B两个对象，成绩分别为59和80；向A发送“修改成绩为60”的请求，方法先检查范围，成功后A变为60，B仍为80。若向A提交101，按本例接口规则拒绝，A仍为60。属性保存状态，方法执行行为；封装不仅是隐藏代码，还规定允许怎样访问和修改状态。","这里的成绩是各对象自己的实例属性，来自同一类不表示实例值自动共享；某些语言还允许类级共享成员，应依声明区分。数据库的属性描述关系中的列，面向对象的属性描述对象状态，不能只因同名就把关系表当成类。继承用于在既有类型上复用或扩展，并非复制粘贴一份程序。"],"boundary":"面向对象不是结构化程序设计的同义词；二者可以在同一系统中结合使用。","id":"y2025q24","sources":[{"year":2025,"q":24,"type":"多选"},{"year":2022,"q":23,"type":"多选"}],"keys":["2025-24","2022-23"],"related":[{"id":"y2025q4","label":"计算思维不是计算机科学家的专属思维","reason":"类抽取共同属性和行为，可与计算思维的抽象联系起来；对象则是这个抽象的具体实例。"},{"id":"y2026q5","label":"顺序、分支和循环可以相互嵌套","reason":"面向对象负责组织数据和操作，方法内部仍能使用顺序、分支和循环，二者可在同一程序中结合。"}],"pointGroups":[{"title":"类与对象先分清","indices":[0,1]},{"title":"属性、方法与封装的实际状态","indices":[2,4,5]},{"title":"继承、多态与消息","indices":[3]}],"pointPresentation":{"4":{"title":"两个实例的方法调用与状态","navigationLabel":"两个实例的方法调用与状态"},"5":{"title":"实例属性与其他语境","navigationLabel":"实例属性与其他语境"}}},{"id":"syllabus-algorithm-strategies","chapter":11,"section":"11.5","origin":"syllabus","type":"考纲补充","topic":"典型问题求解策略","title":"从候选、已知结果和子问题选择算法策略","conclusion":"先确定问题结构和前提，再选择枚举、递推或分治等策略；查找要说明数据是否有序，排序则改变数据次序。","trigger":"考纲要求了解典型问题求解策略；以下是有限教学选例，不把算法名称清单冒称考纲逐项要求。","points":["枚举把有限候选逐一列出并检查条件。例：在1—10中找同时被2和3整除的整数；依次检查，只有6满足。必须明确候选范围、检验条件和输出全部解还是任一解，不能只试几个数就宣称穷尽。","递推从已知结果推出下一步。令S₀=0、Sᵢ=Sᵢ₋₁+i，求1到4之和，结果依次0、1、3、6、10；初值给出起点，递推关系给出更新，目标i=4给出终点。前面的累加循环就是用迭代实现这条递推关系。","分治把问题拆成较小的同类子问题，分别求解后合并。求[8,3,6,2]最大值，可把两半继续拆到单个元素，左半返回8、右半返回6，最后比较得到8。子问题必须有可直接求解的停止情形，合并规则也必须明确；分成小块不自动保证更快。","迭代用循环重复更新状态；递归通过过程调用自身解决子问题。二者不是同义词：递推关系可以用循环实现；分治也需要说明如何求子问题和何时停止。本章只借此区分策略与实现，不展开独立递归或调用栈专题。","线性查找从第一项逐个比较，数据不必预先有序。对[2,5,8,12,16,23,38]找16，依次比较2、5、8、12、16，第5次找到；找不到时检查完所有元素后报告未找到。查找目标是定位已有元素，排序目标是调整次序。","二分查找要求按约定顺序排列的数据，每轮比较当前范围的中间项，再排除不可能的一半。上述升序数组找16：先比中间的12，再比右半中间的23，最后比16，共3次；这里用1基位置、偶数长度取较小中点。未经排序的任意数组不能直接照用。","用左右边界L、R记录当前候选区间，L≤R时才继续；若目标大于中间值，令L=M+1，若小于则R=M−1，相等即找到。L>R表示候选已空。重复值可能在多个位置出现，本例只承诺找到其中一个，不承诺第一个或最后一个。","这些策略为不同问题服务，不能按名称给出永远更优的排名。线性查找最坏要逐项检查；有序、可直接访问中间项的数组可用二分减少比较，但整理数据的成本也要考虑。下一张冒泡卡演示一种排序方法，其“一趟”与“完成全部排序”仍需区分。"],"boundary":"以上用于把考纲概括要求落实为可推演的小例，不表示考纲逐字点名每种策略。本批不扩展贪心、动态规划、选择/插入排序或独立递归课程；网页查找演示只模拟有限整数数组。","sources":[],"keys":[],"searchAliases":["枚举 穷举","递推 迭代","分治 子问题","线性查找 顺序查找","二分查找 折半查找","典型问题求解策略"],"pointGroups":[{"title":"从有限候选与已知结果出发","indices":[0,1]},{"title":"分解子问题并区分实现方式","indices":[2,3]},{"title":"查找的有序前提和边界","indices":[4,5,6,7]}],"related":[{"id":"y2022q43","label":"先初始化，再累加，再推进循环变量","reason":"递推求和可用已有累加循环实现，核对初值和每轮更新。"},{"id":"y2024q69","label":"一趟升序冒泡把最大值推到右端","reason":"查找定位元素，冒泡改变排列；先分任务，再判断是否需要排序。"},{"id":"y2022q33","label":"时间复杂度与空间复杂度不必同向变化","reason":"本卡展示策略执行，复杂度卡解释如何评价主要运算量与额外空间；原策略概览继续可从旧锚点查阅。"}],"pointPresentation":{"0":{"title":"枚举的候选与检验","navigationLabel":"枚举的候选与检验"},"1":{"title":"递推的初值和更新","navigationLabel":"递推的初值和更新"},"2":{"title":"分治的子问题与合并","navigationLabel":"分治的子问题与合并"},"3":{"title":"迭代和递归的边界","navigationLabel":"迭代和递归的边界"},"4":{"title":"线性查找","navigationLabel":"线性查找"},"5":{"title":"二分查找的有序前提","navigationLabel":"二分查找的有序前提"},"6":{"title":"二分区间与终止","navigationLabel":"二分区间与终止"},"7":{"title":"策略选择与成本","navigationLabel":"策略选择与成本"}}},{"q":69,"chapter":11,"section":"11.5","type":"分析","topic":"冒泡排序","title":"一趟升序冒泡把最大值推到右端","trigger":"两道连续分析题先补比较条件，再追踪一趟排序结果。","conclusion":"本例从左向右进行升序冒泡：仅在a[j]＞a[j+1]时交换相邻元素，一趟后本趟最大值到右端；8、5、2、9、7、3的一趟结果是5、2、8、7、3、9。","points":["每一步先比较当前相邻元素，再决定是否交换；不能不看数值就按固定脚本交换。","第一次完整从左向右扫描n个元素需比较n−1对；完成一趟通常只保证一个最大值就位，不代表整个序列有序。","后续趟可缩短尚未排序的范围；有提前结束标记的版本在某一整趟没有交换时即可结束。","保持扫描方向不变，把交换条件改为左值小于右值可得到降序；若从右向左扫描，升序一趟通常是把最小值移到左端，因此要先看循环方向。","相等元素不交换，可保持它们原有的相对次序；判断稳定性应给重复值附上身份，如3甲与3乙。","一般冒泡排序的平均及最坏时间复杂度为O(n²)，额外空间为O(1)；有提前结束判断时，已经有序的输入只需一趟扫描。"],"boundary":"“一趟冒泡”的结果取决于扫描方向和比较条件，不能只背最大值到右端；一趟结束与全表有序是两个状态。","id":"y2024q69","sources":[{"year":2024,"q":69,"type":"分析"},{"year":2024,"q":70,"type":"分析"}],"keys":["2024-69","2024-70"],"comparison":{"headers":["本例操作","保证什么","不保证什么"],"rows":[["一次相邻比较","纠正这一对的逆序关系","整个序列已排序"],["一趟从左到右升序扫描","未排序范围最大值到右端","其余元素全部有序"],["整趟没有交换","当前范围已经有序","所有实现都自动提前结束"]]},"related":[{"id":"y2022q33","label":"时间复杂度与空间复杂度不必同向变化","reason":"比较冒泡的O(n²)时间、O(1)额外空间，以及提前结束版本的有序输入情况，理解复杂度评价的条件。"},{"id":"y2026q5","label":"顺序、分支和循环可以相互嵌套","reason":"先识别扫描循环，再在每次相邻比较后判断是否交换，避免把一趟排序误读成固定交换脚本。"},{"id":"syllabus-algorithm-strategies","label":"从候选、已知结果和子问题选择算法策略","reason":"对照查找与排序的不同目标，并检查二分查找的有序前提。"}],"pointGroups":[{"title":"按扫描方向与交换条件追踪一趟","indices":[0,1,3]},{"title":"整表结束、稳定性与复杂度","indices":[2,4,5]}]}],"sourceCount":460,"years":[2020,2021,2022,2023,2024,2025,2026]};
window.NOTE_REFERENCES={"y2025q4":[["Wing：Computational Thinking","https://www.cs.cmu.edu/~wing/publications/Wing06.pdf"],["作者原文，CMU：计算思维的表示与执行","https://www.cs.cmu.edu/~CompThink/resources/TheLinkWing.pdf"],["CMU大学课程：问题求解步骤","https://www.cs.cmu.edu/~rdriley/112/notes/notes-algorithmic-thinking.html"]],"y2026q42":[["大学教学资料：伪代码","https://www.cs.cmu.edu/~cburch/survey/recurse/pseudocode.html"],["Open University课程：程序流程图","https://www.open.edu/openlearn/mod/oucontent/view.php?id=112559&section=_unit7.4"],["作者教材课程站：条件与循环","https://introcs.cs.princeton.edu/java/13flow/"]],"y2026q6":[["NIST：辗转相除法的余数递推","https://xlinux.nist.gov/dads/HTML/euclidalgo.html"],["MIT OCW讲义：算法特征和评价","https://ocw.mit.edu/courses/1-204-computer-algorithms-in-systems-engineering-spring-2010/8ee75d49f1cb9a947f1d3f15a2aa9e00_MIT1_204S10_lec05.pdf"],["NIST DADS：算法","https://xlinux.nist.gov/dads/HTML/algorithm.html"],["作者原论文，ACM 2006：计算与资源约束","https://www.cs.cmu.edu/~wing/publications/Wing06.pdf"]],"y2022q33":[["Princeton：前缀和预处理与常数时间区间查询","https://competitive-programming.cs.princeton.edu/ps_s24"],["作者教材课程站：算法成本分析","https://introcs.cs.princeton.edu/java/41analysis/"],["大学算法讲义：时间与空间","https://www.cs.cornell.edu/courses/cs312/2002fa/lectures/lec13.htm"]],"y2021q3":[["NIST DADS：队列","https://xlinux.nist.gov/dads/HTML/queue.html"]],"y2026q5":[["作者教材课程站：条件与循环","https://introcs.cs.princeton.edu/java/13flow/"]],"y2022q43":[["Python官方教程：循环和赋值控制流程","https://docs.python.org/3/tutorial/controlflow.html"]],"y2021q33":[["Rice大学OpenStax：while循环","https://openstax.org/books/introduction-python-programming/pages/5-1-while-loop"],["Butte College教材：do-while循环","https://eng.libretexts.org/Courses/Butte_College/Intro_to_Programming_with_Programming_Fundamentals_and_Python_for_Everyone/27:_Additional_Fundamentals_of_Programming/27.06:_Loops/27.6.01:_Do_While_Loop"],["作者教材课程站：条件与循环","https://introcs.cs.princeton.edu/java/13flow/"]],"y2023q69":[["OpenStax：while先检查条件、计数器初始化与推进","https://openstax.org/books/introduction-python-programming/pages/5-1-while-loop"]],"y2025q24":[["Oracle：对象的状态行为、类与封装","https://docs.oracle.com/javase/tutorial/java/concepts/index.html"],["Oracle：多态与不同类型的方法实现","https://docs.oracle.com/javase/tutorial/java/IandI/polymorphism.html"],["Oracle：对象状态与行为","https://docs.oracle.com/javase/tutorial/java/concepts/object.html"],["Oracle：类与实例","https://docs.oracle.com/javase/tutorial/java/concepts/class.html"],["Oracle：实例成员和类成员","https://docs.oracle.com/javase/tutorial/java/javaOO/classvars.html"]],"syllabus-algorithm-strategies":[["山东省教育招生考试院：2026计算机考试要求（二、计算思维；典型策略为概括要求）","https://www.sdzk.cn/Floadup/file/20251129/6389999945835892448300421.pdf"],["NIST DADS：穷举搜索","https://xlinux.nist.gov/dads/HTML/exhaustiveSearch.html"],["NIST DADS：递推关系","https://xlinux.nist.gov/dads/HTML/recurrence.html"],["NIST DADS：分治","https://xlinux.nist.gov/dads/HTML/divideAndConquer.html"],["NIST DADS：线性查找","https://xlinux.nist.gov/dads/HTML/linearSearch.html"],["NIST DADS：二分查找","https://xlinux.nist.gov/dads/HTML/binarySearch.html"],["NIST DADS：递归","https://xlinux.nist.gov/dads/HTML/recursion.html"]],"y2024q69":[["NIST：冒泡排序","https://xlinux.nist.gov/dads/HTML/bubblesort.html"]]};
window.NOTE_DEMOS={"y2025q4":{"kind":"explore","title":"把临床问题做一次计算化拆解","task":"点击步骤，观察计算思维如何跨专业解决问题。","initial":"问题：从大量病例中识别高风险患者。","actions":[{"label":"分解","stage":"拆成数据采集、特征、规则和验证","result":"把复杂问题拆成可处理部分。","tone":"good"},{"label":"抽象","stage":"保留与风险相关的共同特征","result":"忽略无关细节。","tone":"good"},{"label":"自动化","stage":"把明确步骤交给程序重复执行","result":"让解决方案可规模化。","tone":"good"},{"label":"只有程序员能用","stage":"错误","result":"计算思维是通用问题求解方式。","tone":"bad"}]},"y2026q5":{"kind":"explore","title":"把控制结构嵌套起来","task":"点击外层结构，观察内部仍可包含其他基本结构。","initial":"三种基本结构可以组合和嵌套。","actions":[{"label":"顺序结构","stage":"输入 → 判断奇偶 → 输出","result":"整体按顺序推进，其中一步可以是分支。","tone":"good"},{"label":"分支结构","stage":"如果合格，则循环输出证书页","result":"分支内部可以包含循环。","tone":"good"},{"label":"循环结构","stage":"重复读取；若遇结束标志则退出","result":"循环内部可以包含分支。","tone":"good"},{"label":"任意跳转形成混乱流程","stage":"不属于结构化组合","result":"基本结构强调单入口、清晰控制。","tone":"bad"}]}};
window.NOTE_NAVIGATION={"y2025q4":{"related":[{"id":"y2026q42","label":"伪代码用接近自然语言的结构描述算法","reason":"把分解和抽象所得的求解过程写成伪代码，可在选择具体编程语言之前讨论算法。","chapter":11},{"id":"y2025q24","label":"面向对象用类、对象、封装和消息组织程序","reason":"类把共同属性与行为抽象出来，是计算思维中保留关键要素的一种程序组织实例。","chapter":11}],"topics":[]},"y2026q42":{"related":[{"id":"y2026q6","label":"算法必须确定、可行、有限并产生输出","reason":"伪代码没有统一语法，但描述的算法仍需明确、可行、有输出并能终止。","chapter":11},{"id":"y2026q5","label":"顺序、分支和循环可以相互嵌套","reason":"顺序、分支与循环是伪代码中表达控制逻辑的基本结构，缩进应清楚体现嵌套关系。","chapter":11},{"id":"y2025q11","label":"数据库设计不因规模小而省略","reason":"流程图描述算法步骤，E-R图描述实体及联系；看见图形表达不能把两者归为同一种设计。","chapter":10}],"topics":[]},"y2026q6":{"related":[{"id":"y2026q42","label":"伪代码用接近自然语言的结构描述算法","reason":"可先用伪代码表达算法，再检查每一步含义、输入域、输出和终止条件是否清楚。","chapter":11},{"id":"y2022q33","label":"时间复杂度与空间复杂度不必同向变化","reason":"算法在编码前即可分析时间和空间复杂度，运行测试与增长趋势分析回答不同问题。","chapter":11},{"id":"y2021q33","label":"流程图要按箭头追踪，判断位置决定是否先执行一轮","reason":"循环的初值、变量推进和判断位置共同决定结果及能否终止，可用实际追踪检验算法条件。","chapter":11}],"topics":[]},"y2022q33":{"related":[{"id":"y2024q69","label":"一趟升序冒泡把最大值推到右端","reason":"冒泡排序通常用O(n²)时间和O(1)额外空间，是时间与空间增长不必同向的具体例子。","chapter":11},{"id":"y2022q43","label":"先初始化，再累加，再推进循环变量","reason":"将1至10累加推广到n项，逐项扫描需O(n)时间而累计变量只需O(1)额外空间。","chapter":11},{"id":"y2026q45","label":"算力表示计算设备处理数据的能力","reason":"复杂度描述随输入规模的增长，算力描述设备处理能力，不能用一次运行秒数代替复杂度。","chapter":9}],"topics":[]},"y2021q3":{"related":[{"id":"y2026q7","label":"并发、共享、虚拟和异步描述不同操作系统现象","reason":"多队列交替出队可帮助理解任务交错推进；调度次序变化不代表各自应守的操作规则消失。","chapter":2}],"topics":[]},"y2026q5":{"related":[{"id":"y2026q42","label":"伪代码用接近自然语言的结构描述算法","reason":"伪代码用关键词和缩进表达顺序、分支、循环及其嵌套，便于在编码前检查逻辑。","chapter":11},{"id":"y2023q69","label":"计数循环要同时检查初值、边界、条件和累加器","reason":"处理多名学生并只统计不及格者，是循环中嵌套分支的完整实例。","chapter":11},{"id":"y2024q69","label":"一趟升序冒泡把最大值推到右端","reason":"冒泡排序在重复扫描中进行相邻比较并按条件交换，可练习追踪循环与分支的组合。","chapter":11}],"topics":[]},"y2022q43":{"related":[{"id":"y2021q33","label":"流程图要按箭头追踪，判断位置决定是否先执行一轮","reason":"将判断框移到循环体后，或改变更新顺序与边界等号，会改变参与累加的项。","chapter":11},{"id":"y2023q69","label":"计数循环要同时检查初值、边界、条件和累加器","reason":"求和累加器加当前数值，人数计数器只在条件成立时加1；两者都应在循环外初始化。","chapter":11},{"id":"y2022q33","label":"时间复杂度与空间复杂度不必同向变化","reason":"逐项累加可推广为O(n)时间、O(1)额外空间，前缀和则展示为多次查询增加存储的取舍。","chapter":11}],"topics":[]},"y2021q33":{"related":[{"id":"y2022q43","label":"先初始化，再累加，再推进循环变量","reason":"对照先判断的累加循环，观察同样的初始化和更新操作如何因判断位置不同改变执行次数。","chapter":11},{"id":"y2026q5","label":"顺序、分支和循环可以相互嵌套","reason":"先辨认顺序执行、条件判断和循环回边，再按流程箭头追踪每一轮。","chapter":11},{"id":"y2026q6","label":"算法必须确定、可行、有限并产生输出","reason":"循环变量推进和退出条件是算法有限性的具体要求，初始条件与边界情况也需覆盖。","chapter":11}],"topics":[]},"y2023q69":{"related":[{"id":"y2022q43","label":"先初始化，再累加，再推进循环变量","reason":"比较S=S+i与C=C+1，区分累计数值和累计满足条件的记录数，并检查初始化位置。","chapter":11},{"id":"y2026q5","label":"顺序、分支和循环可以相互嵌套","reason":"不及格计数是在循环内嵌套分支，只有分支条件成立才更新计数器。","chapter":11},{"id":"y2021q51","label":"COUNTIF、COUNTIFS与AVERAGEIF：条件计数和条件平均","reason":"COUNTIF把逐行判断后计数封装为表格函数，多条件计数仍要求同一记录满足相应条件。","chapter":4}],"topics":[]},"y2025q24":{"related":[{"id":"y2025q4","label":"计算思维不是计算机科学家的专属思维","reason":"类抽取共同属性和行为，可与计算思维的抽象联系起来；对象则是这个抽象的具体实例。","chapter":11},{"id":"y2026q5","label":"顺序、分支和循环可以相互嵌套","reason":"面向对象负责组织数据和操作，方法内部仍能使用顺序、分支和循环，二者可在同一程序中结合。","chapter":11}],"topics":[]},"syllabus-algorithm-strategies":{"related":[{"id":"y2022q43","label":"先初始化，再累加，再推进循环变量","reason":"递推求和可用已有累加循环实现，核对初值和每轮更新。","chapter":11},{"id":"y2024q69","label":"一趟升序冒泡把最大值推到右端","reason":"查找定位元素，冒泡改变排列；先分任务，再判断是否需要排序。","chapter":11},{"id":"y2022q33","label":"时间复杂度与空间复杂度不必同向变化","reason":"本卡展示策略执行，复杂度卡解释如何评价主要运算量与额外空间；原策略概览继续可从旧锚点查阅。","chapter":11}],"topics":[]},"y2024q69":{"related":[{"id":"y2022q33","label":"时间复杂度与空间复杂度不必同向变化","reason":"比较冒泡的O(n²)时间、O(1)额外空间，以及提前结束版本的有序输入情况，理解复杂度评价的条件。","chapter":11},{"id":"y2026q5","label":"顺序、分支和循环可以相互嵌套","reason":"先识别扫描循环，再在每次相邻比较后判断是否交换，避免把一趟排序误读成固定交换脚本。","chapter":11},{"id":"syllabus-algorithm-strategies","label":"从候选、已知结果和子问题选择算法策略","reason":"对照查找与排序的不同目标，并检查二分查找的有序前提。","chapter":11}],"topics":[]}};
window.NOTE_SEARCH_ENTRIES=[{"id":"y2025q4","kind":"note","chapter":11,"chapterTitle":"计算思维","title":"计算思维不是计算机科学家的专属思维","aliases":[],"fields":[{"anchor":"y2025q4--conclusion","title":"核心结论","text":"计算思维是一套可用于多学科问题求解的思维方法，并非计算机科学家专属。"},{"anchor":"y2025q4--point-0","title":"先理解计算思维与常用方法","aliases":["先理解计算思维与常用方法"],"text":"常见过程包括分解、抽象、模式识别和算法设计。"},{"anchor":"y2025q4--point-1","title":"先理解计算思维与常用方法","aliases":["先理解计算思维与常用方法"],"text":"它可以借助计算机，也可以先在纸面上形成问题模型。"},{"anchor":"y2025q4--point-2","title":"先理解计算思维与常用方法","aliases":["先理解计算思维与常用方法"],"text":"医学、管理、工程和日常决策都可使用计算思维。"},{"anchor":"y2025q4--point-3","title":"先理解计算思维与常用方法","aliases":["先理解计算思维与常用方法"],"text":"抽象保留与目标相关的要素、忽略暂时无关细节；自动化把明确的过程交给机器执行。计算思维是人的问题求解方式，不只是机械操作计算机。"},{"anchor":"y2025q4--point-4","title":"用成绩统计走完问题求解过程","aliases":["用成绩统计走完问题求解过程"],"text":"教学示例：统计班级不及格人数。先确定输入是有效成绩列表，输出是不及格人数；规则为成绩小于60，不必保留与计数无关的姓名和座位号。"},{"anchor":"y2025q4--point-5","title":"用成绩统计走完问题求解过程","aliases":["用成绩统计走完问题求解过程"],"text":"分解过程：核验输入→计数器C置0→逐个读成绩→若成绩\u003c60则C加1→读完输出C。这把现实任务转为可由人或机器执行的步骤。"},{"anchor":"y2025q4--point-6","title":"用成绩统计走完问题求解过程","aliases":["用成绩统计走完问题求解过程"],"text":"用59、60、80检验应输出1；再检查空列表输出0、全部不及格是否等于列表长度。缺考或非法成绩如何处理应先写进输入规则，而不是让程序自行猜测。"},{"anchor":"y2025q4--point-7","title":"计算思维的对象与常用角度","aliases":["计算思维的对象与常用角度","先理解计算思维与常用方法"],"text":"计算思维关注怎样表示问题并形成可执行的求解过程：先明确要解决什么、哪些信息重要，再把步骤表达得足够清楚，供人或机器执行。分解、抽象、模式识别、算法化是常用理解角度，不是唯一固定清单；只会点击软件按钮不等于已经掌握这种思维。"},{"anchor":"y2025q4--point-8","title":"问题求解过程与模式识别","aliases":["问题求解过程与模式识别","先理解计算思维与常用方法"],"text":"从任务到解法可分为明确需求与输入输出、建立简化模型、设计步骤、检查结果、必要时编码实现。模式识别是在不同实例中找可复用规律，例如统计不及格和统计缺勤都可采用“逐项判断、符合时计数”；判断条件不同，不能照搬结论。"},{"anchor":"y2025q4--boundary","title":"易错边界","text":"计算思维不等于会操作软件，也不等于任何问题都必须写程序。"},{"anchor":"y2025q4--sources","title":"来源与核验记录","text":"真题直接考查计算思维的适用范围和常见方法。 2023 第3题 2025 第4题 2021 第23题 Wing：Computational Thinking 作者原文，CMU：计算思维的表示与执行 CMU大学课程：问题求解步骤"},{"anchor":"y2025q4--demo","title":"把临床问题做一次计算化拆解","text":"点击步骤，观察计算思维如何跨专业解决问题。"}]},{"id":"y2026q42","kind":"note","chapter":11,"chapterTitle":"计算思维","title":"伪代码用接近自然语言的结构描述算法","aliases":[],"fields":[{"anchor":"y2026q42--conclusion","title":"核心结论","text":"伪代码用结构化、近似程序的文字表达算法逻辑，不要求遵守某门语言的完整语法。"},{"anchor":"y2026q42--point-0","title":"算法与三种表示方式","aliases":["算法与三种表示方式"],"text":"伪代码应清楚体现输入、处理、输出和控制结构。"},{"anchor":"y2026q42--point-1","title":"完整伪代码和流程图符号","aliases":["完整伪代码和流程图符号"],"text":"它便于编码前讨论逻辑。例如求3、8、5的最大值：m先取3，看到8更大就改为8，再与5比较后保持8，最后输出8。若只写“选一个合适的数”，因为“合适”未定义，无法据此执行。"},{"anchor":"y2026q42--point-2","title":"算法与三种表示方式","aliases":["算法与三种表示方式"],"text":"流程图也可表示算法，但形式是图形符号和流程线。"},{"anchor":"y2026q42--point-3","title":"算法与三种表示方式","aliases":["算法与三种表示方式"],"text":"自然语言、伪代码、流程图可描述算法步骤；E-R图描述实体及联系，不是算法流程图。"},{"anchor":"y2026q42--point-4","title":"算法与表示法","aliases":["算法与表示法","算法与三种表示方式"],"text":"算法是为解决一类问题而规定的明确、有限、可执行步骤；表示法只是把这些步骤写出来或画出来。自然语言便于交流，但需避免歧义；流程图突出路径和条件；伪代码突出结构与变量。换一种表示法，不等于换了所解决的问题。"},{"anchor":"y2026q42--point-5","title":"三数最大值完整伪代码","aliases":["三数最大值完整伪代码","完整伪代码和流程图符号"],"text":"三数取最大值的完整伪代码可写为：输入a、b、c；m←a；若b>m则m←b；若c>m则m←c；输出m。输入3、8、5时m依次为3、8、8。两个判断都要执行，不能擅自把第二个改成第一个的“否则”；输入3、8、9时仍须继续比较9。"},{"anchor":"y2026q42--point-6","title":"流程图常见符号","aliases":["流程图常见符号","完整伪代码和流程图符号"],"text":"常见程序流程图用起止框表示开始/结束、矩形表示处理或赋值、平行四边形表示输入/输出、菱形表示判断，箭头表示下一步。判断框还要读清分支标注；同样的框，连线方向不同也可能执行不同算法。具体图形记号以题目约定为准。"},{"anchor":"y2026q42--boundary","title":"易错边界","text":"伪代码没有唯一语法，却仍应保持关键词、缩进和变量含义一致。"},{"anchor":"y2026q42--sources","title":"来源与核验记录","text":"题目要求填写一种不依赖具体编程语言的算法表示方法。 2026 第42题 2022 第5题 大学教学资料：伪代码 Open University课程：程序流程图 作者教材课程站：条件与循环"},{"anchor":"y2026q42--demo","title":"三数比较：明确规则才有确定输出","text":"修改数值，比较明确算法与没有定义判断规则的伪代码。"}]},{"id":"y2026q6","kind":"note","chapter":11,"chapterTitle":"计算思维","title":"算法必须确定、可行、有限并产生输出","aliases":[],"fields":[{"anchor":"y2026q6--conclusion","title":"核心结论","text":"算法可以没有外部输入，但至少有一个输出；每一步应确定、可行，并在有限步骤后结束，也可以在编码前分析正确性与复杂度。"},{"anchor":"y2026q6--point-0","title":"问题、输入域与算法特征","aliases":["问题、输入域与算法特征"],"text":"确定性要求每一步含义明确，可行性要求操作能在有限资源下执行。"},{"anchor":"y2026q6--point-1","title":"算法评价与程序实现","aliases":["算法评价与程序实现"],"text":"时间复杂度和空间复杂度可依据算法结构分析。"},{"anchor":"y2026q6--point-2","title":"算法评价与程序实现","aliases":["算法评价与程序实现"],"text":"程序是算法的一种实现，测试实现不能代替算法论证。"},{"anchor":"y2026q6--point-3","title":"问题、输入域与算法特征","aliases":["问题、输入域与算法特征"],"text":"算法允许零个或多个输入，但必须有一个或多个输出；“输入必须有、输出可以无”把条件写反。"},{"anchor":"y2026q6--point-4","title":"用辗转相除检查终止","aliases":["用辗转相除检查终止"],"text":"辗转相除法每轮用“当前除数、非零余数”作为下一轮输入。例如48÷18余12，18÷12余6，12÷6余0，输出当前除数6。非零余数逐轮严格变小且不能无限下降，因此会终止；首轮整除时直接输出该轮除数。"},{"anchor":"y2026q6--point-5","title":"输入域、算法与程序","aliases":["输入域、算法与程序","问题、输入域与算法特征"],"text":"算法面向一类问题，对满足输入约定的不同实例都应成立，而非只碰巧算对一组数。先确定输入域与任务，再看步骤和终点；程序用某种编程语言实现这些步骤，同一算法可以有不同语言实现，也可先由人手工追踪。下方最大公约数演示限定两个正整数，这是演示输入域，不是所有算法都必须有两个输入。"},{"anchor":"y2026q6--point-6","title":"确定性与现实资源边界","aliases":["确定性与现实资源边界","问题、输入域与算法特征"],"text":"确定性要求步骤含义明确，并不要求不同输入产生同一个数值。理论上可计算与现实中能高效完成也不同：即使存在求解步骤，输入规模很大时仍可能超出可接受的时间或存储资源。不能由理论可计算推出任意现有电脑都能迅速求解。"},{"anchor":"y2026q6--boundary","title":"易错边界","text":"伪代码仍需转成可执行程序；“程序跑起来”也不等于算法正确或高效。"},{"anchor":"y2026q6--worked-0","title":"真题怎么判断 · 2024年第4题","text":"2024 第4题 判断算法是否必须编程后才能评价。 算法是问题求解的明确步骤，程序是算法的一种实现。 即使尚未编码，也能检查步骤是否正确、是否终止，并估算主要操作次数与额外空间。 因此“必须实现后才能评价”的绝对前提不成立；具体运行时间还会受语言实现和机器环境影响。 把抽象算法的分析等同于程序跑出来的秒数。 拿两个寻找最大值的方法先数比较次数，再谈实现语言；能分析复杂度不等于已经知道实测耗时。  2024原卷完整题干及全部选项已读；配套答案已核，未据此称官方答案"},{"anchor":"y2026q6--sources","title":"来源与核验记录","text":"真题从输出、可行性和实现前评价考查算法的基本特征。 2024 第4题 2025 第5题 2026 第6题 2022 第6题 NIST：辗转相除法的余数递推 MIT OCW讲义：算法特征和评价 NIST DADS：算法 作者原论文，ACM 2006：计算与资源约束"},{"anchor":"y2026q6--demo","title":"让辗转相除真正走到终点","text":"输入两个正整数，逐轮观察被除数、除数和余数。"}]},{"id":"y2022q33","kind":"note","chapter":11,"chapterTitle":"计算思维","title":"时间复杂度与空间复杂度不必同向变化","aliases":[],"fields":[{"anchor":"y2022q33--conclusion","title":"核心结论","text":"时间复杂度描述运算量随输入规模增长的趋势；空间复杂度描述所需存储空间的增长趋势，两者没有必然正比例关系。"},{"anchor":"y2022q33--point-0","title":"先定评价口径，再比较时空取舍","aliases":["先定评价口径，再比较时空取舍"],"text":"同一问题可用缓存结果换取更少重复计算，这是以空间换时间。"},{"anchor":"y2022q33--point-1","title":"先定评价口径，再比较时空取舍","aliases":["先定评价口径，再比较时空取舍"],"text":"逐个扫描n项求和，主要加法次数随n成比例增长，通常为O(n)时间；只保留当前累计值，需要O(1)额外空间。O(1)表示额外空间不随n增长，不是完全不占空间。"},{"anchor":"y2022q33--point-2","title":"先定评价口径，再比较时空取舍","aliases":["先定评价口径，再比较时空取舍"],"text":"前缀和把“到当前位置为止的和”预先存好。例如数据3、5、2对应前缀和0、3、8、10，第2至3项的和可算10−3=7，不用再逐项相加。建表需O(n)时间和空间，之后每次区间求和为O(1)。"},{"anchor":"y2022q33--point-3","title":"典型策略与增长趋势的最小联系","aliases":["典型策略与增长趋势的最小联系"],"text":"枚举检查候选解，递推从已知小规模结果推进，分治把问题分成较小子问题再合并结果；是否适用取决于问题结构。二分查找要依赖有序数据，不能对任意无序表直接使用。"},{"anchor":"y2022q33--point-4","title":"典型策略与增长趋势的最小联系","aliases":["典型策略与增长趋势的最小联系"],"text":"分析循环时看实际执行次数：从1到n每次加1通常是线性次数；每次把规模减半通常是对数次数。嵌套循环不能只数层数，还要检查各层边界及依赖关系。"},{"anchor":"y2022q33--point-5","title":"时间与额外空间的统计口径","aliases":["时间与额外空间的统计口径","先定评价口径，再比较时空取舍"],"text":"先约定输入规模与统计口径，再谈复杂度。本章示例以主要运算次数观察增长趋势，以“额外空间”表示不含原输入的辅助存储；O(n)等记号不等于准确次数。一次实测更快不能单独证明复杂度更低，增加缓存也不保证任何查询都更划算。"},{"anchor":"y2022q33--boundary","title":"易错边界","text":"复杂度描述规模增长趋势，不是一次运行秒数或某台电脑的内存容量；应说明是否统计额外空间。前缀和适合数据不变且有多次查询的情形，数据修改后原缓存可能需要更新。"},{"anchor":"y2022q33--sources","title":"来源与核验记录","text":"从算法复杂度的判断与应用整理。 2022 第33题 Princeton：前缀和预处理与常数时间区间查询 作者教材课程站：算法成本分析 大学算法讲义：时间与空间"},{"anchor":"y2022q33--demo","title":"用缓存换计算：区间求和工作台","text":"先载入数据、建立前缀和，再查询；真实运算记录与大规模成本估算分开。"}]},{"id":"y2021q3","kind":"note","chapter":11,"chapterTitle":"计算思维","title":"队列先进先出，多队列交错不能打乱各自顺序","aliases":[],"fields":[{"anchor":"y2021q3--conclusion","title":"核心结论","text":"队列从队尾加入、从队头取出，遵循FIFO；多个队列可以交替出队，但各自内部先后顺序保持不变。"},{"anchor":"y2021q3--point-0","title":"相关内容","aliases":[],"text":"车道一按A、B、C、D排队，车道二按E、F、G、H排队，每次只能放行某车道队首。"},{"anchor":"y2021q3--point-1","title":"相关内容","aliases":[],"text":"ABEFCDGH是合法交错；AFEBCDGH中F先于E，违反第二队列顺序。"},{"anchor":"y2021q3--point-2","title":"相关内容","aliases":[],"text":"判断一串输出是否合法，可分别抽出属于每个队列的元素，检查相对次序是否保持。"},{"anchor":"y2021q3--point-3","title":"相关内容","aliases":[],"text":"栈是后进先出LIFO，操作限制与队列不同。"},{"anchor":"y2021q3--boundary","title":"易错边界","text":"队列先后只约束本队列；不能据此断言A必定先于另一队列的E。"},{"anchor":"y2021q3--sources","title":"来源与核验记录","text":"围绕队列的识别、应用与易错边界整理。 2021 第3题 NIST DADS：队列"},{"anchor":"y2021q3--demo","title":"两队过桥：只能放行队首","text":"交替放行两个队列，观察合法次序怎样形成。"}]},{"id":"y2026q5","kind":"note","chapter":11,"chapterTitle":"计算思维","title":"顺序、分支和循环可以相互嵌套","aliases":[],"fields":[{"anchor":"y2026q5--conclusion","title":"核心结论","text":"顺序按先后执行，分支按条件选择路径，循环在终止条件控制下重复；三者可以结构化嵌套。"},{"anchor":"y2026q5--point-0","title":"顺序与条件路径","aliases":["顺序与条件路径"],"text":"分支可表达条件成立执行A，否则执行B。"},{"anchor":"y2026q5--point-1","title":"循环和结构化组合","aliases":["循环和结构化组合"],"text":"循环由循环体和循环控制条件构成。"},{"anchor":"y2026q5--point-2","title":"循环和结构化组合","aliases":["循环和结构化组合"],"text":"结构化组合有助于保持流程可追踪。"},{"anchor":"y2026q5--point-3","title":"顺序执行和赋值","aliases":["顺序执行和赋值","顺序与条件路径"],"text":"顺序结构按既定先后执行，赋值会改变后续语句读到的值。例如x←2；x←x+3；输出x，结果为5。顺序并非要求所有表达式都不含比较，而是描述控制流按先后推进。"},{"anchor":"y2026q5--point-4","title":"独立判断与互斥分支","aliases":["独立判断与互斥分支","顺序与条件路径"],"text":"分支由条件选择路径。若成绩\u003c60则输出“不及格”，否则输出“及格”，一次只走其中一条；两个独立的“若”则各自判断，可能都执行。需要多个互斥结果时可用多分支，但必须先看题目各条件如何衔接。"},{"anchor":"y2026q5--point-5","title":"循环追踪四要素","aliases":["循环追踪四要素","循环和结构化组合"],"text":"追踪循环统一检查初值、条件、循环体和更新：写出初始变量，沿箭头执行，逐步改值，检查继续条件，直到出口才读最终输出。先判断型可能0次，后判断型至少1次；漏掉推进或在循环内反复清零累加器，会破坏原来的计算任务。Excel的IF是返回结果的函数，不能仅凭名称把它等同于整段程序控制流。"},{"anchor":"y2026q5--boundary","title":"易错边界","text":"“外层是顺序结构”不意味着内部不能含分支或循环。"},{"anchor":"y2026q5--sources","title":"来源与核验记录","text":"两道题综合判断三种基本控制结构的含义和嵌套关系。 2025 第25题 2026 第5题 作者教材课程站：条件与循环"},{"anchor":"y2026q5--demo","title":"把控制结构嵌套起来","text":"点击外层结构，观察内部仍可包含其他基本结构。"}]},{"id":"y2022q43","kind":"note","chapter":11,"chapterTitle":"计算思维","title":"先初始化，再累加，再推进循环变量","aliases":[],"fields":[{"anchor":"y2022q43--conclusion","title":"核心结论","text":"S=0、i=1；当i≤10时执行S=S+i、i=i+1，最终S为55。"},{"anchor":"y2022q43--point-0","title":"相关内容","aliases":[],"text":"S保存累计结果，i保存当前加数。从(S,i)=(0,1)开始，前三轮执行后依次为(1,2)、(3,3)、(6,4)：每轮先把当前i加进S，再推进i。"},{"anchor":"y2022q43--point-1","title":"相关内容","aliases":[],"text":"S应在循环外初始化。若每轮相加前都重新令S=0，前面的和就被覆盖；本例最终只会留下最后一次的加数10。"},{"anchor":"y2022q43--point-2","title":"相关内容","aliases":[],"text":"最后一次相加使用i=10，之后i变成11，条件不成立才退出。"},{"anchor":"y2022q43--point-3","title":"相关内容","aliases":[],"text":"可用等差数列1+…+10=10×11÷2核验，不替代逐步理解循环。"},{"anchor":"y2022q43--boundary","title":"易错边界","text":"S=S+i是赋值更新，不是代数恒等式；把推进语句提前会改变被累加的数列。"},{"anchor":"y2022q43--sources","title":"来源与核验记录","text":"从累加循环的判断与应用整理。 2022 第43题 Python官方教程：循环和赋值控制流程"},{"anchor":"y2022q43--demo","title":"逐轮执行1到n的累加","text":"每次执行一轮，查看S与i的实际更新；n=0时循环体执行0次。"}]},{"id":"y2021q33","kind":"note","chapter":11,"chapterTitle":"计算思维","title":"流程图要按箭头追踪，判断位置决定是否先执行一轮","aliases":[],"fields":[{"anchor":"y2021q33--conclusion","title":"核心结论","text":"本例先执行S=S+k，再令k=k+3，最后判断k＜10；从S=0、k=1开始，累加1、4、7后输出12。判断位置、条件方向和变量更新顺序要一起追踪。"},{"anchor":"y2021q33--point-0","title":"初始化并按真实执行顺序追踪状态","aliases":["初始化并按真实执行顺序追踪状态"],"text":"每轮记录执行前的k、累加后的S、更新后的k以及继续条件真假，按流程箭头实际经过的顺序执行。"},{"anchor":"y2021q33--point-1","title":"初始化并按真实执行顺序追踪状态","aliases":["初始化并按真实执行顺序追踪状态"],"text":"第一轮S=1、k=4；第二轮S=5、k=7；第三轮S=12、k=10，条件不成立退出，因此10未被累加。"},{"anchor":"y2021q33--point-2","title":"改变边界或判断位置后再比较","aliases":["改变边界或判断位置后再比较"],"text":"把继续条件改成k≤10，会再累加10，随后k变为13，输出变为22；边界等号是否存在会改变执行次数。"},{"anchor":"y2021q33--point-3","title":"改变边界或判断位置后再比较","aliases":["改变边界或判断位置后再比较"],"text":"后测试循环先执行循环体，至少执行一次；先测试循环先判断，初始条件不成立时可能执行0次。"},{"anchor":"y2021q33--point-4","title":"改变边界或判断位置后再比较","aliases":["改变边界或判断位置后再比较"],"text":"例如仍取S=0、k=1，但边界设为1：本例后测试写法会先加1再退出；将条件移到循环体之前则一次也不加。"},{"anchor":"y2021q33--point-5","title":"初始化并按真实执行顺序追踪状态","aliases":["初始化并按真实执行顺序追踪状态"],"text":"S应在循环外初始化；循环变量必须按规则推进，使退出条件最终能满足。赋值S=S+k是用旧值计算后写回，不是代数恒等式。"},{"anchor":"y2021q33--boundary","title":"易错边界","text":"判断框移到循环体前后、把＜改成≤、或把k的更新提前，都可能改变结果；箭头上的“是/否”通向哪里也必须与条件一起阅读。"},{"anchor":"y2021q33--comparison","title":"知识点对照","text":" 条件与结构 累加项 输出 本例后测试，k＜10 1、4、7 12 本例后测试，k≤10 1、4、7、10 22 边界1，后测试 1 1 边界1，先测试 无 0"},{"anchor":"y2021q33--sources","title":"来源与核验记录","text":"围绕先执行后判断的识别、应用与易错边界整理。 2021 第33题 Rice大学OpenStax：while循环 Butte College教材：do-while循环 作者教材课程站：条件与循环"},{"anchor":"y2021q33--demo","title":"按流程箭头走：先加，再更新，再判断","text":"每次执行一轮，或改变终止边界看最后一项是否进入和。"}]},{"id":"y2023q69","kind":"note","chapter":11,"chapterTitle":"计算思维","title":"计数循环要同时检查初值、边界、条件和累加器","aliases":[],"fields":[{"anchor":"y2023q69--conclusion","title":"核心结论","text":"先用i保证每人成绩恰好处理一次，再用C只统计不及格者。若从i=1开始，每轮处理一人后加1，45人用i≤45；C在循环前置0，成绩＜60时才执行C=C+1。"},{"anchor":"y2023q69--point-0","title":"初值、边界与每轮执行顺序","aliases":["初值、边界与每轮执行顺序"],"text":"初值和边界必须配套：i从1到45，含两端，共45次；i从0到44，同样45次，可写i＜45。若把i=1与i＜45搭配，只处理44人；把i=0与i≤45搭配则处理46次。"},{"anchor":"y2023q69--point-1","title":"初值、边界与每轮执行顺序","aliases":["初值、边界与每轮执行顺序"],"text":"C=C+1是赋值：先读出旧C，加1，再写回C；不是解方程。i记录处理进度，C记录满足条件的人数，即使某人成绩及格，i也仍要推进。"},{"anchor":"y2023q69--point-2","title":"不及格条件与三值计数轨迹","aliases":["不及格条件与三值计数轨迹"],"text":"只有成绩＜60时才增加C；恰好60分不满足这一条件。循环总次数等于处理人数，分支执行次数才是不及格人数。"},{"anchor":"y2023q69--point-3","title":"不及格条件与三值计数轨迹","aliases":["不及格条件与三值计数轨迹"],"text":"用三个人缩小推演：成绩依次59、60、58，C从0开始；读59后C=1，读60后仍为1，读58后C=2。共执行3轮，但只执行2次C=C+1，最终输出2。"},{"anchor":"y2023q69--point-4","title":"初始化位置为何改变结果","aliases":["初始化位置为何改变结果"],"text":"C必须在循环前初始化一次。若每轮都把C置0，本例最终得到1，只反映最后一人成绩；若漏掉初始化，累计值没有可靠起点。"},{"anchor":"y2023q69--boundary","title":"易错边界","text":"这里按“先判断是否还有人→读取本人成绩→按条件计数→推进i”推演；改变读入位置或更新顺序后应重新走一遍。初值、最后一次处理的序号、退出时的i与最终C是四个不同问题。"},{"anchor":"y2023q69--sources","title":"来源与核验记录","text":"两道连续分析题补全处理45名学生的循环条件，并解释不及格人数累加语句。 2023 第69题 2023 第70题 OpenStax：while先检查条件、计数器初始化与推进"},{"anchor":"y2023q69--demo","title":"逐个读成绩，只有不及格才加计数","text":"编辑成绩列表，每轮读一个值；循环次数与不及格人数分开累计。"}]},{"id":"y2025q24","kind":"note","chapter":11,"chapterTitle":"计算思维","title":"面向对象用类、对象、封装和消息组织程序","aliases":[],"fields":[{"anchor":"y2025q24--conclusion","title":"核心结论","text":"面向对象以类和对象为核心，通过封装组织数据与操作，并通过消息或方法调用建立对象协作。"},{"anchor":"y2025q24--point-0","title":"类与对象先分清","aliases":["类与对象先分清"],"text":"类描述一类对象共同的属性和行为。例如“学生”类可规定学号、姓名、成绩等属性，以及修改成绩等方法。"},{"anchor":"y2025q24--point-1","title":"类与对象先分清","aliases":["类与对象先分清"],"text":"对象是类的具体实例。“学号01的王宁”和“学号02的李明”可来自同一学生类，但各自保存自己的成绩状态。"},{"anchor":"y2025q24--point-2","title":"属性、方法与封装的实际状态","aliases":["属性、方法与封装的实际状态"],"text":"封装把数据与操作组织在一起，并控制外部访问。例如通过“修改成绩”方法检查0—100的范围，再更新对象内部成绩；调用者按公开接口使用，不必直接改内部存储。"},{"anchor":"y2025q24--point-3","title":"继承、多态与消息","aliases":["继承、多态与消息"],"text":"继承复用或扩展已有类型；多态使相同接口可由不同对象给出各自实现。例如同样调用“计算面积”，圆对象按圆的规则计算，矩形对象按长×宽计算。消息或方法调用用来请求对象完成操作。"},{"anchor":"y2025q24--point-4","title":"两个实例的方法调用与状态","aliases":["两个实例的方法调用与状态","属性、方法与封装的实际状态"],"text":"沿一次调用看对象状态：同一“学生”类建立A、B两个对象，成绩分别为59和80；向A发送“修改成绩为60”的请求，方法先检查范围，成功后A变为60，B仍为80。若向A提交101，按本例接口规则拒绝，A仍为60。属性保存状态，方法执行行为；封装不仅是隐藏代码，还规定允许怎样访问和修改状态。"},{"anchor":"y2025q24--point-5","title":"实例属性与其他语境","aliases":["实例属性与其他语境","属性、方法与封装的实际状态"],"text":"这里的成绩是各对象自己的实例属性，来自同一类不表示实例值自动共享；某些语言还允许类级共享成员，应依声明区分。数据库的属性描述关系中的列，面向对象的属性描述对象状态，不能只因同名就把关系表当成类。继承用于在既有类型上复用或扩展，并非复制粘贴一份程序。"},{"anchor":"y2025q24--boundary","title":"易错边界","text":"面向对象不是结构化程序设计的同义词；二者可以在同一系统中结合使用。"},{"anchor":"y2025q24--sources","title":"来源与核验记录","text":"题目要求识别面向对象程序设计的基本思想与方法。 2025 第24题 2022 第23题 Oracle：对象的状态行为、类与封装 Oracle：多态与不同类型的方法实现 Oracle：对象状态与行为 Oracle：类与实例 Oracle：实例成员和类成员"},{"anchor":"y2025q24--demo","title":"同一个类，两个独立对象","text":"先创建两个学生对象，再通过方法改成绩；观察实例状态、校验和取消。"}]},{"id":"syllabus-algorithm-strategies","kind":"note","chapter":11,"chapterTitle":"计算思维","title":"从候选、已知结果和子问题选择算法策略","aliases":["枚举 穷举","递推 迭代","分治 子问题","线性查找 顺序查找","二分查找 折半查找","典型问题求解策略"],"fields":[{"anchor":"syllabus-algorithm-strategies--conclusion","title":"核心结论","text":"先确定问题结构和前提，再选择枚举、递推或分治等策略；查找要说明数据是否有序，排序则改变数据次序。"},{"anchor":"syllabus-algorithm-strategies--point-0","title":"枚举的候选与检验","aliases":["枚举的候选与检验","从有限候选与已知结果出发"],"text":"枚举把有限候选逐一列出并检查条件。例：在1—10中找同时被2和3整除的整数；依次检查，只有6满足。必须明确候选范围、检验条件和输出全部解还是任一解，不能只试几个数就宣称穷尽。"},{"anchor":"syllabus-algorithm-strategies--point-1","title":"递推的初值和更新","aliases":["递推的初值和更新","从有限候选与已知结果出发"],"text":"递推从已知结果推出下一步。令S₀=0、Sᵢ=Sᵢ₋₁+i，求1到4之和，结果依次0、1、3、6、10；初值给出起点，递推关系给出更新，目标i=4给出终点。前面的累加循环就是用迭代实现这条递推关系。"},{"anchor":"syllabus-algorithm-strategies--point-2","title":"分治的子问题与合并","aliases":["分治的子问题与合并","分解子问题并区分实现方式"],"text":"分治把问题拆成较小的同类子问题，分别求解后合并。求[8,3,6,2]最大值，可把两半继续拆到单个元素，左半返回8、右半返回6，最后比较得到8。子问题必须有可直接求解的停止情形，合并规则也必须明确；分成小块不自动保证更快。"},{"anchor":"syllabus-algorithm-strategies--point-3","title":"迭代和递归的边界","aliases":["迭代和递归的边界","分解子问题并区分实现方式"],"text":"迭代用循环重复更新状态；递归通过过程调用自身解决子问题。二者不是同义词：递推关系可以用循环实现；分治也需要说明如何求子问题和何时停止。本章只借此区分策略与实现，不展开独立递归或调用栈专题。"},{"anchor":"syllabus-algorithm-strategies--point-4","title":"线性查找","aliases":["线性查找","查找的有序前提和边界"],"text":"线性查找从第一项逐个比较，数据不必预先有序。对[2,5,8,12,16,23,38]找16，依次比较2、5、8、12、16，第5次找到；找不到时检查完所有元素后报告未找到。查找目标是定位已有元素，排序目标是调整次序。"},{"anchor":"syllabus-algorithm-strategies--point-5","title":"二分查找的有序前提","aliases":["二分查找的有序前提","查找的有序前提和边界"],"text":"二分查找要求按约定顺序排列的数据，每轮比较当前范围的中间项，再排除不可能的一半。上述升序数组找16：先比中间的12，再比右半中间的23，最后比16，共3次；这里用1基位置、偶数长度取较小中点。未经排序的任意数组不能直接照用。"},{"anchor":"syllabus-algorithm-strategies--point-6","title":"二分区间与终止","aliases":["二分区间与终止","查找的有序前提和边界"],"text":"用左右边界L、R记录当前候选区间，L≤R时才继续；若目标大于中间值，令L=M+1，若小于则R=M−1，相等即找到。L>R表示候选已空。重复值可能在多个位置出现，本例只承诺找到其中一个，不承诺第一个或最后一个。"},{"anchor":"syllabus-algorithm-strategies--point-7","title":"策略选择与成本","aliases":["策略选择与成本","查找的有序前提和边界"],"text":"这些策略为不同问题服务，不能按名称给出永远更优的排名。线性查找最坏要逐项检查；有序、可直接访问中间项的数组可用二分减少比较，但整理数据的成本也要考虑。下一张冒泡卡演示一种排序方法，其“一趟”与“完成全部排序”仍需区分。"},{"anchor":"syllabus-algorithm-strategies--boundary","title":"易错边界","text":"以上用于把考纲概括要求落实为可推演的小例，不表示考纲逐字点名每种策略。本批不扩展贪心、动态规划、选择/插入排序或独立递归课程；网页查找演示只模拟有限整数数组。"},{"anchor":"syllabus-algorithm-strategies--sources","title":"来源与核验记录","text":"考纲要求了解典型问题求解策略；以下是有限教学选例，不把算法名称清单冒称考纲逐项要求。  山东省教育招生考试院：2026计算机考试要求（二、计算思维；典型策略为概括要求） NIST DADS：穷举搜索 NIST DADS：递推关系 NIST DADS：分治 NIST DADS：线性查找 NIST DADS：二分查找 NIST DADS：递归"},{"anchor":"syllabus-algorithm-strategies--demo","title":"先核有序前提，再逐步查找","text":"对同一数组执行线性或二分查找，实际记录区间、比较对象、次数和终止状态。"}]},{"id":"y2024q69","kind":"note","chapter":11,"chapterTitle":"计算思维","title":"一趟升序冒泡把最大值推到右端","aliases":[],"fields":[{"anchor":"y2024q69--conclusion","title":"核心结论","text":"本例从左向右进行升序冒泡：仅在a[j]＞a[j+1]时交换相邻元素，一趟后本趟最大值到右端；8、5、2、9、7、3的一趟结果是5、2、8、7、3、9。"},{"anchor":"y2024q69--point-0","title":"按扫描方向与交换条件追踪一趟","aliases":["按扫描方向与交换条件追踪一趟"],"text":"每一步先比较当前相邻元素，再决定是否交换；不能不看数值就按固定脚本交换。"},{"anchor":"y2024q69--point-1","title":"按扫描方向与交换条件追踪一趟","aliases":["按扫描方向与交换条件追踪一趟"],"text":"第一次完整从左向右扫描n个元素需比较n−1对；完成一趟通常只保证一个最大值就位，不代表整个序列有序。"},{"anchor":"y2024q69--point-2","title":"整表结束、稳定性与复杂度","aliases":["整表结束、稳定性与复杂度"],"text":"后续趟可缩短尚未排序的范围；有提前结束标记的版本在某一整趟没有交换时即可结束。"},{"anchor":"y2024q69--point-3","title":"按扫描方向与交换条件追踪一趟","aliases":["按扫描方向与交换条件追踪一趟"],"text":"保持扫描方向不变，把交换条件改为左值小于右值可得到降序；若从右向左扫描，升序一趟通常是把最小值移到左端，因此要先看循环方向。"},{"anchor":"y2024q69--point-4","title":"整表结束、稳定性与复杂度","aliases":["整表结束、稳定性与复杂度"],"text":"相等元素不交换，可保持它们原有的相对次序；判断稳定性应给重复值附上身份，如3甲与3乙。"},{"anchor":"y2024q69--point-5","title":"整表结束、稳定性与复杂度","aliases":["整表结束、稳定性与复杂度"],"text":"一般冒泡排序的平均及最坏时间复杂度为O(n²)，额外空间为O(1)；有提前结束判断时，已经有序的输入只需一趟扫描。"},{"anchor":"y2024q69--boundary","title":"易错边界","text":"“一趟冒泡”的结果取决于扫描方向和比较条件，不能只背最大值到右端；一趟结束与全表有序是两个状态。"},{"anchor":"y2024q69--comparison","title":"知识点对照","text":" 本例操作 保证什么 不保证什么 一次相邻比较 纠正这一对的逆序关系 整个序列已排序 一趟从左到右升序扫描 未排序范围最大值到右端 其余元素全部有序 整趟没有交换 当前范围已经有序 所有实现都自动提前结束"},{"anchor":"y2024q69--sources","title":"来源与核验记录","text":"两道连续分析题先补比较条件，再追踪一趟排序结果。 2024 第69题 2024 第70题 NIST：冒泡排序"},{"anchor":"y2024q69--demo","title":"输入自己的数组，比较一次或跑完一趟冒泡","text":"可改升降序、重复值和负数；每一步的交换、趟数与比较次数都实际计算。"}]}];
